            error!(session = %session_id, error = %e, "Rate limit exceeded");
            return Err(anyhow::anyhow!("Rate limit exceeded: {}", e));
        }

        // Acquire semaphore permit — actually blocks when at concurrency limit
        let _permit = self
            .concurrency_semaphore
            .acquire()
            .await

