85:                vec![BROKER_EVENT_SUBID.into()],
86:                "grpc:emqx.exhook.v3".into(),
87:                None,
88:                ChangeSource::Grpc,
89:            )
90:            .await;
91:        if let Err(error) = result {
92:            tracing::error!(%error, event_type, "could not record broker observation");
93:            return Err(anyhow::anyhow!(error));
