        };
        assert!(same_seal(&expected, &"a".repeat(64), "{\"version\":2}"));
        assert!(!same_seal(&expected, &"b".repeat(64), "{\"version\":2}"));
        assert!(!same_seal(&expected, &"a".repeat(64), "{\"version\":3}"));
    }

