        .unwrap();
        let crate::state_tree_fold::StateTreeFold::Present(merged) =
            crate::state_tree_fold::merge_plugin_object_fields(
                Some(&previous),
                PLUGIN,
                &op_plugins::canonical::plugin_path(PLUGIN),
                &fields,
            )
            .unwrap()
        else {
